    # 1) gap-fill: repeat until stable: same-color cells in a row with exactly one bg between -> fill
    changed=True
    while changed:
        changed=False
        for r in range(h):
            row=orig[r]; 
            for c in range(w-2):
                if row[c]!=0 and row[c]==row[c+2]==row[c+1]+0 and row[c+1]==0:
                    pass
        # simpler: scan for pattern X.X (X !=0, middle ==0)
        for r in range(h):
            row=list(orig[r])
            for c in range(w-2):
                x=row[c]
                if x!=0 and row[c+1]==0 and row[c+2]==x:
                    row[c+1]=x; changed=True
            orig[r]=np.array(row)
    # 2) find components per color (4-conn), get tops and fill columns
    comp=[]
    seen=np.zeros_like(orig,bool)
    for v in range(1,10):
        ys,xs=np.where(orig==v)
        for (r,c) in zip(ys,xs):
            if seen[r][c]: continue
            st=[(r,c)];seen[r][c]=True;cells=[]
            while st:
                rr,cc=st.pop();cells.append((rr,cc))
                for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=rr+dr,cc+dc
                    if 0<=nr<h and 0<=nc<w and orig[nr][nc]==v and not seen[nr][nc]:
                        seen[nr][nc]=True;st.append((nr,nc))
            comp.append(cells)
    # order by top row
    comp.sort(key=lambda cs:min(r for r,c in cs))
    paint=orig.copy()
    for cells in comp:
        top=min(r for r,c in cells)
        rowset=set(c for r,c in cells if r==top)
        # fill columns: gap columns = orig-bg within span of top row; vertical stem -> own column
        cols=set()
        tr=next(r for r,c in cells if r==top)
        cols={c for c in range(min(c for _,c in cells),max(c for _,c in cells)+1) if orig[tr][c]==0}|{c for r,c in cells}
        if len({r for r,c in cells})==1: cols={c for r,c in cells}  # pure horizontal run: nothing (gaps handled)
        elif len({c for r,c in cells})==1: cols={next(c for r,c in cells)}  # vertical stem
        for c in cols:
            r=top-1
            while r>=0 and paint[r][c]==0 and paint[r][c]!=orig[r][c] or (r>=0 and paint[r][c]==0 and orig[r][c]==0):
                pass
            # walk up painting background cells; stop at obstacle
            r=top-1
            while r>=0 and paint[r][c]==0:
                paint[r][c]=v; r-=1
    return paint.tolist()

